// ---------------------------------------------------------------------------
// LaunchAgent respawn policy (scripts/lib/launch-agent-check.js). The agent
// stays KeepAlive, but a daemon that dies right after starting is restarted
// at most once per ThrottleInterval; release-check.sh verifies that on the
// installed plist, and the same static check runs here on any platform.
// ---------------------------------------------------------------------------

const LAUNCH_AGENT_CHECK = path.join(ROOT, 'scripts', 'lib', 'launch-agent-check.js');

test('launch-agent-check: the plist portname install writes keeps the daemon alive with a respawn throttle', () => {
  const { respawnPolicyProblems, parsePlist } = require('../scripts/lib/launch-agent-check');
  const { plist } = require('../bin/portname');
  const generated = plist({ dir: '/Users/demo/a&b <dir>', nodePath: '/usr/bin/node', entryPath: '/x/portname.js', extraPath: '/p/bin' });
  assert.deepStrictEqual(respawnPolicyProblems(generated), []);
  const agent = parsePlist(generated);
  assert.strictEqual(agent.EnvironmentVariables.PORTNAME_DIR, '/Users/demo/a&b <dir>', 'escaped values read back');
  assert.deepStrictEqual(agent.ProgramArguments, ['/usr/bin/node', '/x/portname.js', 'daemon']);

  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'launch-agent-check.'));
  try {
    const run = (xml) => {
      const file = path.join(dir, 'agent.plist');
      fs.writeFileSync(file, xml);
      try {
        execFileSync(process.execPath, [LAUNCH_AGENT_CHECK, file], { stdio: 'pipe' });
        return { code: 0, stderr: '' };
      } catch (err) {
        return { code: err.status, stderr: String(err.stderr) };
      }
    };
    assert.strictEqual(run(generated).code, 0);
    const throttle = '<key>ThrottleInterval</key><integer>30</integer>';
    assert.ok(generated.includes(throttle));
    const without = generated.replace(throttle, '');
    const res = run(without);
    assert.strictEqual(res.code, 1, 'a plist without the throttle must fail the gate');
    assert.match(res.stderr, /ThrottleInterval must be an integer >= 30 seconds \(got undefined\)/);
    // The throttle only counts at the top level, not tucked into another dict.
    const nested = without.replace('<key>PATH</key>', `${throttle}\n    <key>PATH</key>`);
    assert.match(run(nested).stderr, /ThrottleInterval must be/);
    assert.match(run(generated.replace(throttle, '<key>ThrottleInterval</key><integer>5</integer>')).stderr, /got 5/);
    assert.match(run(generated.replace(throttle, '<key>ThrottleInterval</key><string>30</string>')).stderr, /got "30"/);
    assert.match(run(generated.replace('<key>KeepAlive</key><true/>', '<key>KeepAlive</key><false/>')).stderr,
      /KeepAlive must be true/);
    assert.match(run(generated.replace('<key>KeepAlive</key><true/>',
      '<key>KeepAlive</key><dict><key>SuccessfulExit</key><false/></dict>')).stderr, /KeepAlive must be true/);
    // Unreadable or ambiguous plists fail closed instead of being guessed at.
    assert.match(run(generated.replace(throttle, `${throttle}${throttle}`)).stderr, /duplicate plist key ThrottleInterval/);
    assert.strictEqual(run(generated.slice(0, generated.indexOf('<key>RunAtLoad</key>'))).code, 1);
    assert.strictEqual(run('{"KeepAlive": true, "ThrottleInterval": 30}').code, 1);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test('release-check.sh: checks the respawn throttle of the installed LaunchAgent plist', () => {
  const src = fs.readFileSync(RELEASE_CHECK_SCRIPT, 'utf8');
  const install = src.indexOf('run_stubbed "$RESOURCES/bin/portname-cli" install');
  const check = src.indexOf('node "$SCRIPT_DIR/lib/launch-agent-check.js" "$PLIST" || fail');
  const uninstall = src.indexOf('run_stubbed "$PAYLOAD_DIR/bin/portname" uninstall');
  assert.ok(check !== -1, 'release-check must run the respawn-policy gate on the installed plist');
  assert.ok(install < check && check < uninstall, 'after the isolated install wrote the plist, before uninstall removes it');
});

// ---------------------------------------------------------------------------
// release-check.sh's isolated install (step 6) runs the real `install`,
// which refuses a state dir whose control socket path exceeds the Unix
// socket limit. Under macOS's per-user $TMPDIR (/var/folders/<2>/<30>/T/,
// 49 bytes) the socket path came to 105 bytes, so the gate could never pass.
// ---------------------------------------------------------------------------

test('release-check.sh: the isolated control socket path fits the socket path limit on macOS', () => {
  const { MAX_SOCKET_PATH_BYTES } = require('../lib/config');
  const src = fs.readFileSync(RELEASE_CHECK_SCRIPT, 'utf8');
  const tpl = /^ISOTMP="\$\(mktemp -d "?([^")]+)"?\)"$/m.exec(src);
  assert.ok(tpl, 'release-check must create its isolated root with mktemp -d');
  // Longest form on macOS: a $TMPDIR-based template at the stock per-user
  // length, and every root resolved physically (/tmp and /var live under
  // /private), as the payload wrapper and node resolve them.
  const stockTmpdir = `/var/folders/xx/${'x'.repeat(30)}/T/`;
  const template = tpl[1].replace(/\$\{TMPDIR(?::-[^}]*)?\}|\$TMPDIR\b/g, stockTmpdir);
  assert.ok(!template.includes('$'), `the template must not depend on other variables: ${template}`);
  assert.ok(path.posix.isAbsolute(template), `the template must be absolute: ${template}`);
  const physical = path.posix.normalize(template.replace(/^\/(tmp|var)(?=\/)/, '/private/$1'));

  const home = /^ISO_HOME="\$ISOTMP\/([^"]+)"$/m.exec(src);
  const stateDir = /^export PORTNAME_DIR="\$ISO_HOME\/([^"]+)"$/m.exec(src);
  const sockName = /^const SOCK = path\.join\(DIR, '([^']+)'\);$/m.exec(fs.readFileSync(path.join(ROOT, 'bin', 'portname.js'), 'utf8'));
  assert.ok(home && stateDir && sockName, 'isolated HOME, PORTNAME_DIR and the socket name must be derivable');
  const sock = path.posix.join(physical, home[1], stateDir[1], sockName[1]);
  assert.ok(Buffer.byteLength(sock) <= MAX_SOCKET_PATH_BYTES,
    `${sock} is ${Buffer.byteLength(sock)} bytes; install refuses more than ${MAX_SOCKET_PATH_BYTES}`);
  assert.match(src, /^ISOTMP="\$\(cd "\$ISOTMP" && pwd -P\)"$/m, 'the root must be canonicalized physically');
});

// The payload wrapper's reinstall exits 0 even when it takes the
// developer-checkout branch (agent PATH without the payload runtime, node
// outside the payload), so its plist is checked like the first install's.
test('release-check.sh: agent paths are checked after the bundle install and again after the payload reinstall', () => {
  const src = fs.readFileSync(RELEASE_CHECK_SCRIPT, 'utf8');
  const def = src.indexOf('check_agent_paths() {');
  assert.ok(def !== -1, 'release-check must define the agent path check');
  const body = src.slice(def, src.indexOf('\n}\n', def));
  assert.ok(body.includes('plutil -extract ProgramArguments json'), 'the check covers ProgramArguments');
  assert.ok(body.includes('plutil -extract EnvironmentVariables.PATH raw'), 'the check covers the daemon PATH');
  assert.ok(body.includes('"$PAYLOAD_DIR/runtime/bin:"*'), 'the daemon PATH must start with the payload runtime');
  const install = src.indexOf('run_stubbed "$RESOURCES/bin/portname-cli" install');
  const reinstall = src.indexOf('run_stubbed "$PAYLOAD_DIR/bin/portname" install');
  const calls = [...src.matchAll(/^check_agent_paths "/gm)].map((m) => m.index);
  assert.ok(install !== -1 && reinstall !== -1 && calls.length > 0 && def < calls[0]);
  assert.ok(calls.some((i) => i > install && i < reinstall), 'checked after the bundle install');
  assert.ok(calls.some((i) => i > reinstall), 'checked again after the payload reinstall');
});
